package dev.jdgarita.frnk.presentation.componentCore

import dev.jdgarita.frnk.presentation.resources.images.SemanticImage
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi
import kotlinx.serialization.Serializable

@Serializable
sealed class FrnkImageSource {
    @Serializable
    data class Semantic(val semanticImage: SemanticImage) : FrnkImageSource()

    @Serializable
    data class Remote(
        val urlString: String,
        val imageType: ImageType = ImageType.ImageEngine,
        val sizeMultiplier: Float = 1.0f
    ) : FrnkImageSource()

    @Serializable
    data class Raw(val data: ByteArray) : FrnkImageSource()

    @Serializable
    enum class ImageType {
        Generic,
        ImageEngine
    }
}

object FakeImageSource {
    val raw = FrnkImageSource.Raw(data = imageData)
    val semantic = FrnkImageSource.Semantic(semanticImage = SemanticImage.SwiftlyProductImage)

    @Suppress("ktlint:standard:max-line-length")
    @OptIn(ExperimentalEncodingApi::class)
    private val imageData: ByteArray
        get() {
            val imageString = ""
            return Base64.decode(imageString)
        }
}